    /// <summary>
    /// Default activities to be done while initializing
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get form data source args</param>
    [
        FormEventHandler(formStr(CustParameters), FormEventType::Initialized),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void CustParameters_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        METCustParameters metCustParms;

        metCustParms = METCustParameters::Find();
    }
